      hu: ["Alsó-Ausztria", "Bécsi környék", "Növekvő település", "Ipari területek"],
      ro: ["Austria Inferioară", "Zona metropolitană Viena", "Comună în dezvoltare", "Zone industriale"],
      en: ["Lower Austria", "Vienna outskirts", "Growing community", "Industrial zones"],
